// Typings for vendor/pb-sim.js, generated by peoples-bitcoin's
// `npm run build:sim`. The bundle is the pure world host (src/server in that
// repo): sim, content, chat, trade and AOI. All I/O comes through PbSimIO.
declare var PB_SIM_VERSION: string;

interface PbSimPresence {
  userId: string;
  sessionId: string;
  username: string;
}

interface PbSimWho {
  userId: string;
  sid: string;
}

interface PbSimOnline {
  world: number;
  matchId: string;
  at: number;
  pf?: string;
  fr?: string[];
}

interface PbSimIO {
  nowMs(): number;
  loadCharacters(userIds: string[]): { [userId: string]: { data: unknown; version: string } | null };
  saveCharacters(rows: { userId: string; data: unknown; version?: string }[]): {
    ok: boolean;
    versions?: { [userId: string]: string };
    conflicts?: string[];
    error?: string;
  };
  loadWorld(): unknown;
  saveWorld(data: unknown): void;
  earnTickets(who: PbSimWho, amount: number, reason: string, key: string): { [k: string]: unknown };
  spendTickets(who: PbSimWho, shopId: string, itemId: string, packs: number, key: string): { [k: string]: unknown };
  sellItem(who: PbSimWho, shopId: string, itemId: string, packs: number, key: string): { [k: string]: unknown };
  ticketBalance(who: PbSimWho): { [k: string]: unknown };
  readOnline(userIds: string[]): { [userId: string]: PbSimOnline | null };
  writeOnline(userId: string, entry: PbSimOnline | null): void;
  signalWorld(matchId: string, data: string): string | null;
  resolveUsername(name: string): { userId: string; username: string } | null;
  log(level: "info" | "warn" | "error", msg: string): void;
}

interface PbSimOutbound {
  op: number;
  data: string;
  to: string[] | null;
}

interface PbSimLoopResult {
  messages: PbSimOutbound[];
  kick: string[];
  label?: string;
}

interface PbSimWorldHost {
  joinAttempt(p: PbSimPresence, vars: { [k: string]: string } | null): { accept: boolean; reason?: string };
  join(presences: PbSimPresence[]): void;
  leave(presences: PbSimPresence[]): void;
  message(sender: PbSimPresence, op: number, data: string): void;
  loop(): PbSimLoopResult;
  signal(data: string): string;
  shutdown(): PbSimLoopResult;
  label(): string;
  size(): number;
}

declare var PbSim: {
  version: string;
  createWorldHost(opts: { worldNo: number; matchId: string; seed: number; io: PbSimIO }): PbSimWorldHost;
  /** players in one world for `ticks` ticks, `walkShare` of them clicking each tick; phase timings in ms. */
  benchWorld(players: number, ticks: number, walkShare: number, now: () => number): { [k: string]: number };
  constants(): { PROTOCOL_VERSION: number; SIM_VERSION: string; GAME_ID: string; OP: { [k: string]: number } };
};
